import React, { useState } from 'react';
import { ShoppingBag, Search, Settings, ShieldCheck, Clock, Sparkles, Watch, User } from 'lucide-react';

export default function BarraNavegacion({
  cartCount,
  onOpenCart,
  onOpenSettings,
  isConnected,
  isFallback,
  storeName,
  searchQuery,
  setSearchQuery,
  onTriggerLoader,
  user,
  onOpenAuth
}) {
  const [showSearch, setShowSearch] = useState(false);

  return (
    <header style={{
      position: 'sticky',
      top: 0,
      zIndex: 50,
      backgroundColor: 'rgba(255, 255, 255, 0.94)',
      backdropFilter: 'blur(20px)',
      WebkitBackdropFilter: 'blur(20px)',
      borderBottom: '1px solid rgba(115, 96, 91, 0.16)',
      boxShadow: '0 4px 20px rgba(45, 66, 98, 0.05)',
      transition: 'all 0.3s ease'
    }}>
      {/* Top micro-bar en perla suave */}
      <div style={{
        backgroundColor: '#f6f3ee',
        borderBottom: '1px solid rgba(115, 96, 91, 0.12)',
        padding: '7px 24px',
        display: 'flex',
        justifyContent: 'space-between',
        alignItems: 'center',
        fontSize: '0.74rem',
        letterSpacing: '0.08em',
        color: 'var(--c-taupe)'
      }}>
        <div className="marquee-container">
          <div className="marquee-text">
            ENVIOS A TODO EL PERÚ &nbsp;&nbsp;•&nbsp;&nbsp; ENTREGA EN TU DOMICILIO &nbsp;&nbsp;•&nbsp;&nbsp; 3 AÑOS DE GARANTIA &nbsp;&nbsp;•&nbsp;&nbsp; ESCRIBE A NUESTRA LINEA DE VENTAS POR WHATSAPP +51 998788599
          </div>
        </div>

        <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
          {/* Botón para probar la pantalla de carga */}
          {onTriggerLoader && (
            <button
              onClick={onTriggerLoader}
              title="Ver animación del dial de cronógrafo analógico"
              style={{
                background: 'rgba(255, 59, 48, 0.08)',
                border: '1px solid rgba(255, 59, 48, 0.35)',
                color: '#ff3b30',
                padding: '4px 12px',
                borderRadius: '9999px',
                cursor: 'pointer',
                fontSize: '0.72rem',
                fontWeight: 700,
                display: 'flex',
                alignItems: 'center',
                gap: '6px',
                transition: 'all 0.2s ease'
              }}
              onMouseEnter={(e) => {
                e.currentTarget.style.background = '#ff3b30';
                e.currentTarget.style.color = '#ffffff';
              }}
              onMouseLeave={(e) => {
                e.currentTarget.style.background = 'rgba(255, 59, 48, 0.08)';
                e.currentTarget.style.color = '#ff3b30';
              }}
            >
              ⏱️ Probar Loader
            </button>
          )}

          {/* Indicador de conexión SaaS */}
          <button
            onClick={onOpenSettings}
            title="Configurar conexión con tu SaaS"
            style={{
              background: isConnected ? 'rgba(45, 66, 98, 0.08)' : 'rgba(208, 150, 131, 0.15)',
              border: `1px solid ${isConnected ? 'var(--c-indigo)' : 'var(--c-blush)'}`,
              color: isConnected ? 'var(--c-indigo)' : 'var(--c-deep-purple)',
              padding: '4px 12px',
              borderRadius: '9999px',
              cursor: 'pointer',
              fontSize: '0.72rem',
              fontWeight: 600,
              display: 'flex',
              alignItems: 'center',
              gap: '6px',
              transition: 'all 0.2s ease'
            }}
          >
            <Settings size={12} color="var(--c-indigo)" />
            {isConnected ? 'SaaS Conectado' : 'Conectar con SaaS / Demostración'}
          </button>
        </div>
      </div>

      {/* Barra Principal Luminosa */}
      <div style={{
        maxWidth: '1360px',
        margin: '0 auto',
        padding: '16px 24px',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'space-between',
        gap: '24px'
      }}>
        {/* Brand Logo */}
        <a href="#" style={{ textDecoration: 'none', display: 'flex', flexDirection: 'column', alignItems: 'center', gap: '8px' }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: '16px' }}>
            <Watch size={28} color="#5e1743" strokeWidth={1.5} />
            <div style={{ width: '1.5px', height: '36px', backgroundColor: '#000' }}></div>
            <div style={{ fontSize: '2.2rem', fontFamily: '"Cinzel", serif', color: '#5e1743', lineHeight: 1, letterSpacing: '0.05em' }}>
              TP
            </div>
          </div>
          <div style={{
            fontSize: '0.65rem',
            letterSpacing: '0.45em',
            fontFamily: '"Cinzel", serif',
            color: '#000',
            textTransform: 'uppercase',
            marginLeft: '0.45em'
          }}>
            TEMPO PRECISO
          </div>
        </a>

        {/* Enlaces de Navegación de Alta Categoría */}
        <nav style={{ display: 'flex', alignItems: 'center', gap: '22px', flexWrap: 'wrap' }}>
          {[
            { label: 'Hombre', href: '#catalogo', tag: 'Hombre' },
            { label: 'Mujer', href: '#catalogo', tag: 'Mujer' },
            { label: 'Marcas', href: '#catalogo', isHighlight: true },
            { label: 'Novedades', href: '#catalogo', badge: 'Nuevo' },
            { label: 'Ofertas', href: '#catalogo', badge: 'VIP' },
            { label: 'Accesorios', href: '#catalogo' }
          ].map((item, idx) => (
            <a
              key={idx}
              href={item.href}
              style={{
                color: item.isHighlight ? 'var(--c-indigo)' : 'var(--c-deep-purple)',
                textDecoration: 'none',
                fontSize: '0.8rem',
                letterSpacing: '0.12em',
                textTransform: 'uppercase',
                fontFamily: 'var(--font-serif)',
                fontWeight: 500,
                transition: 'all 0.2s ease',
                position: 'relative',
                display: 'flex',
                alignItems: 'center',
                gap: '4px',
                padding: '4px 0'
              }}
              onMouseEnter={(e) => {
                e.currentTarget.style.color = 'var(--c-blush)';
              }}
              onMouseLeave={(e) => {
                e.currentTarget.style.color = item.isHighlight ? 'var(--c-indigo)' : 'var(--c-deep-purple)';
              }}
            >
              {item.label}
              {item.badge && (
                <span style={{
                  fontSize: '0.58rem',
                  backgroundColor: item.badge === 'VIP' ? 'var(--c-blush)' : 'var(--c-indigo)',
                  color: '#ffffff',
                  padding: '2px 5px',
                  borderRadius: '4px',
                  lineHeight: 1,
                  fontWeight: 800,
                  letterSpacing: '0.05em'
                }}>
                  {item.badge}
                </span>
              )}
            </a>
          ))}
        </nav>

        {/* Acciones */}
        <div style={{ display: 'flex', alignItems: 'center', gap: '16px' }}>
          {/* Botón de Mi Cuenta VIP (Login) */}
          <button
            onClick={onOpenAuth}
            title={user ? `Cuenta VIP: ${user.nombre}` : "Mi Cuenta VIP / Iniciar Sesión"}
            style={{
              height: '42px',
              padding: user ? '0 16px' : '0',
              width: user ? 'auto' : '42px',
              borderRadius: user ? '9999px' : '50%',
              background: user ? 'var(--c-deep-purple)' : '#ffffff',
              border: user ? '1px solid var(--c-blush)' : '1px solid var(--border-light)',
              color: user ? '#ffffff' : 'var(--c-deep-purple)',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              gap: '8px',
              cursor: 'pointer',
              boxShadow: '0 2px 8px rgba(45, 66, 98, 0.08)',
              transition: 'all 0.2s ease'
            }}
            onMouseEnter={(e) => {
              e.currentTarget.style.borderColor = 'var(--c-blush)';
            }}
            onMouseLeave={(e) => {
              e.currentTarget.style.borderColor = user ? 'var(--c-blush)' : 'var(--border-light)';
            }}
          >
            <User size={18} color={user ? 'var(--c-blush)' : 'var(--c-deep-purple)'} />
            {user && (
              <span style={{
                fontSize: '0.8rem',
                fontFamily: 'var(--font-serif)',
                fontWeight: 700,
                letterSpacing: '0.04em'
              }}>
                {user.nombre.split(' ')[0]} (VIP)
              </span>
            )}
          </button>

          {/* Buscador */}
          {showSearch ? (
            <div style={{
              display: 'flex',
              alignItems: 'center',
              backgroundColor: '#ffffff',
              borderRadius: '9999px',
              padding: '6px 14px',
              border: '1px solid var(--c-indigo)',
              boxShadow: '0 4px 15px rgba(45, 66, 98, 0.1)'
            }}>
              <Search size={16} color="var(--c-indigo)" style={{ marginRight: '8px' }} />
              <input
                type="text"
                placeholder="Buscar reloj, calibre..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                autoFocus
                style={{
                  background: 'transparent',
                  border: 'none',
                  outline: 'none',
                  color: 'var(--c-deep-purple)',
                  fontSize: '0.85rem',
                  width: '180px',
                  fontWeight: 500
                }}
              />
              <button
                onClick={() => setShowSearch(false)}
                style={{
                  background: 'none',
                  border: 'none',
                  color: 'var(--c-taupe)',
                  cursor: 'pointer',
                  fontSize: '0.9rem',
                  marginLeft: '4px'
                }}
              >
                ✕
              </button>
            </div>
          ) : (
            <button
              onClick={() => setShowSearch(true)}
              title="Buscar en el catálogo"
              style={{
                width: '42px',
                height: '42px',
                borderRadius: '50%',
                background: '#ffffff',
                border: '1px solid var(--border-light)',
                color: 'var(--c-deep-purple)',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                cursor: 'pointer',
                boxShadow: '0 2px 8px rgba(45, 66, 98, 0.06)',
                transition: 'all 0.2s ease'
              }}
              onMouseEnter={(e) => {
                e.currentTarget.style.borderColor = 'var(--c-blush)';
                e.currentTarget.style.color = 'var(--c-indigo)';
              }}
              onMouseLeave={(e) => {
                e.currentTarget.style.borderColor = 'var(--border-light)';
                e.currentTarget.style.color = 'var(--c-deep-purple)';
              }}
            >
              <Search size={18} />
            </button>
          )}

          {/* Bolsa VIP */}
          <button
            onClick={onOpenCart}
            style={{
              position: 'relative',
              background: 'var(--c-indigo)',
              border: 'none',
              borderRadius: '9999px',
              padding: '10px 20px',
              cursor: 'pointer',
              display: 'flex',
              alignItems: 'center',
              gap: '10px',
              color: '#ffffff',
              boxShadow: '0 4px 18px rgba(45, 66, 98, 0.25)',
              transition: 'all 0.3s ease'
            }}
            onMouseEnter={(e) => {
              e.currentTarget.style.transform = 'translateY(-1px)';
              e.currentTarget.style.boxShadow = '0 6px 22px rgba(45, 66, 98, 0.35)';
              e.currentTarget.style.background = 'var(--c-indigo-hover)';
            }}
            onMouseLeave={(e) => {
              e.currentTarget.style.transform = 'translateY(0)';
              e.currentTarget.style.boxShadow = '0 4px 18px rgba(45, 66, 98, 0.25)';
              e.currentTarget.style.background = 'var(--c-indigo)';
            }}
          >
            <ShoppingBag size={17} color="#ffffff" />
            <span style={{
              fontSize: '0.82rem',
              fontFamily: 'var(--font-serif)',
              letterSpacing: '0.08em',
              fontWeight: 700
            }}>
              Bolsa VIP
            </span>
            {cartCount > 0 && (
              <span style={{
                backgroundColor: 'var(--c-blush)',
                color: '#ffffff',
                fontSize: '0.72rem',
                fontWeight: 800,
                width: '20px',
                height: '20px',
                borderRadius: '50%',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                boxShadow: '0 0 8px var(--c-blush)'
              }}>
                {cartCount}
              </span>
            )}
          </button>
        </div>
      </div>
    </header>
  );
}
